	"github.com/knirvcorp/knirvagent/pkg/voice"
)

//go:generate cp -r ../../workspace .
//go:embed workspace
var embeddedFiles embed.FS

var (
	version   = "dev"
	gitCommit string
	buildTime string
	goVersion string
)

const logo = "🤖"

// formatVersion returns the version string with optional git commit
func formatVersion() string {
	v := version
	if gitCommit != "" {
		v += fmt.Sprintf(" (git: %s)", gitCommit)
	}
	return v
}

// formatBuildInfo returns build time and go version info
func formatBuildInfo() (build string, goVer string) {
	if buildTime != "" {
		build = buildTime
	}
	goVer = goVersion
	if goVer == "" {
		goVer = runtime.Version()
	}
	return
}

func printVersion() {
	fmt.Printf("%s knirvagent %s\n", logo, formatVersion())
	build, goVer := formatBuildInfo()
	if build != "" {
		fmt.Printf("  Build: %s\n", build)
	}
	if goVer != "" {
		fmt.Printf("  Go: %s\n", goVer)
	}
}

func copyDirectory(src, dst string) error {
	return filepath.Walk(src, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, path)
		if err != nil {
			return err
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, info.Mode())
		}

		srcFile, err := os.Open(path)
		if err != nil {
			return err
		}
		defer srcFile.Close()

		dstFile, err := os.OpenFile(dstPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, info.Mode())
		if err != nil {
			return err
		}
		defer dstFile.Close()

		_, err = io.Copy(dstFile, srcFile)
		return err
	})
}

func main() {
	if len(os.Args) < 2 {
		printHelp()
		os.Exit(1)
	}

	command := os.Args[1]

	switch command {
	case "onboard":
		onboard()
	case "agent":
		agentCmd()
	case "gateway":
		gatewayCmd()
	case "server":
		serverCmd()
	case "status":
		statusCmd()
	case "migrate":
		migrateCmd()
	case "auth":
		authCmd()
	case "cron":
		cronCmd()
	case "skills":
		if len(os.Args) < 3 {
			skillsHelp()
			return
		}

		subcommand := os.Args[2]

		cfg, err := loadConfig()
		if err != nil {
			fmt.Printf("Error loading config: %v\n", err)
			os.Exit(1)
		}

		workspace := cfg.WorkspacePath()
		installer := skills.NewSkillInstaller(workspace)
		// 获取全局配置目录和内置 skills 目录
		globalDir := filepath.Dir(getConfigPath())
		globalSkillsDir := filepath.Join(globalDir, "skills")
		builtinSkillsDir := filepath.Join(globalDir, "knirvagent", "skills")
		skillsLoader := skills.NewSkillsLoader(workspace, globalSkillsDir, builtinSkillsDir)

		switch subcommand {
		case "list":
			skillsListCmd(skillsLoader)
		case "install":
			skillsInstallCmd(installer)
		case "remove", "uninstall":
			if len(os.Args) < 4 {
				fmt.Println("Usage: knirvagent skills remove <skill-name>")
				return
			}
			skillsRemoveCmd(installer, os.Args[3])
		case "install-builtin":
			skillsInstallBuiltinCmd(workspace)
		case "list-builtin":
			skillsListBuiltinCmd()
		case "search":
			skillsSearchCmd(installer)
		case "show":
			if len(os.Args) < 4 {
				fmt.Println("Usage: knirvagent skills show <skill-name>")
				return
			}
			skillsShowCmd(skillsLoader, os.Args[3])
		default:
			fmt.Printf("Unknown skills command: %s\n", subcommand)
			skillsHelp()
		}
	case "version", "--version", "-v":
		printVersion()
	default:
		fmt.Printf("Unknown command: %s\n", command)
		printHelp()
		os.Exit(1)
	}
}

func printHelp() {
	fmt.Printf("%s knirvagent - Personal AI Assistant v%s\n\n", logo, version)
	fmt.Println("Usage: knirvagent <command>")
	fmt.Println()
	fmt.Println("Commands:")
	fmt.Println("  onboard     Initialize knirvagent configuration and workspace")
	fmt.Println("  agent       Interact with the agent directly")
	fmt.Println("  auth        Manage authentication (login, logout, status)")
	fmt.Println("  gateway     Start knirvagent gateway")
	fmt.Println("  server      Start knirvagent as HTTP server on Unix socket")
	fmt.Println("  status      Show knirvagent status")
	fmt.Println("  cron        Manage scheduled tasks")
	fmt.Println("  migrate     Migrate from OpenClaw to KnirvAgent")
	fmt.Println("  skills      Manage skills (install, list, remove)")
	fmt.Println("  version     Show version information")
}

func onboard() {
	configPath := getConfigPath()

	if _, err := os.Stat(configPath); err == nil {
		fmt.Printf("Config already exists at %s\n", configPath)
		fmt.Print("Overwrite? (y/n): ")
		var response string
		fmt.Scanln(&response)
		if response != "y" {
			fmt.Println("Aborted.")
			return
		}
	}

	cfg := config.DefaultConfig()
	if err := config.SaveConfig(configPath, cfg); err != nil {
		fmt.Printf("Error saving config: %v\n", err)
		os.Exit(1)
	}

	workspace := cfg.WorkspacePath()
	createWorkspaceTemplates(workspace)

	fmt.Printf("%s knirvagent is ready!\n", logo)
	fmt.Println("\nNext steps:")
	fmt.Println("  1. Add your API key to", configPath)
	fmt.Println("     Get one at: https://openrouter.ai/keys")
	fmt.Println("  2. Chat: knirvagent agent -m \"Hello!\"")
}

func copyEmbeddedToTarget(targetDir string) error {
	// Ensure target directory exists
	if err := os.MkdirAll(targetDir, 0755); err != nil {
		return fmt.Errorf("Failed to create target directory: %w", err)
	}

	// Walk through all files in embed.FS
	err := fs.WalkDir(embeddedFiles, "workspace", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		// Skip directories
		if d.IsDir() {
			return nil
		}

		// Read embedded file
		data, err := embeddedFiles.ReadFile(path)
		if err != nil {
			return fmt.Errorf("Failed to read embedded file %s: %w", path, err)
		}

		new_path, err := filepath.Rel("workspace", path)
		if err != nil {
			return fmt.Errorf("Failed to get relative path for %s: %v\n", path, err)
		}

		// Build target file path
		targetPath := filepath.Join(targetDir, new_path)

		// Ensure target file's directory exists
		if err := os.MkdirAll(filepath.Dir(targetPath), 0755); err != nil {
			return fmt.Errorf("Failed to create directory %s: %w", filepath.Dir(targetPath), err)
		}

		// Write file
		if err := os.WriteFile(targetPath, data, 0644); err != nil {
			return fmt.Errorf("Failed to write file %s: %w", targetPath, err)
		}

		return nil
	})

	return err
}

func createWorkspaceTemplates(workspace string) {
	err := copyEmbeddedToTarget(workspace)
	if err != nil {
		fmt.Printf("Error copying workspace templates: %v\n", err)
	}
}

func migrateCmd() {
	if len(os.Args) > 2 && (os.Args[2] == "--help" || os.Args[2] == "-h") {
		migrateHelp()
		return
	}

	opts := migrate.Options{}

	args := os.Args[2:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--dry-run":
			opts.DryRun = true
		case "--config-only":
			opts.ConfigOnly = true
		case "--workspace-only":
			opts.WorkspaceOnly = true
		case "--force":
			opts.Force = true
		case "--refresh":
			opts.Refresh = true
		case "--openclaw-home":
			if i+1 < len(args) {
				opts.OpenClawHome = args[i+1]
				i++
			}
		case "--knirvagent-home":
			if i+1 < len(args) {
				opts.KnirvAgentHome = args[i+1]
				i++
			}
		default:
			fmt.Printf("Unknown flag: %s\n", args[i])
			migrateHelp()
			os.Exit(1)
		}
	}

	result, err := migrate.Run(opts)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}

	if !opts.DryRun {
		migrate.PrintSummary(result)
	}
}

func migrateHelp() {
	fmt.Println("\nMigrate from OpenClaw to KnirvAgent")
	fmt.Println()
	fmt.Println("Usage: knirvagent migrate [options]")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("  --dry-run          Show what would be migrated without making changes")
	fmt.Println("  --refresh          Re-sync workspace files from OpenClaw (repeatable)")
	fmt.Println("  --config-only      Only migrate config, skip workspace files")
	fmt.Println("  --workspace-only   Only migrate workspace files, skip config")
	fmt.Println("  --force            Skip confirmation prompts")
	fmt.Println("  --openclaw-home    Override OpenClaw home directory (default: ~/.openclaw)")
	fmt.Println("  --knirvagent-home  Override KnirvAgent home directory (default: ~/.knirvagent)")
	fmt.Println()
	fmt.Println("Examples:")
	fmt.Println("  knirvagent migrate              Detect and migrate from OpenClaw")
	fmt.Println("  knirvagent migrate --dry-run    Show what would be migrated")
	fmt.Println("  knirvagent migrate --refresh    Re-sync workspace files")
	fmt.Println("  knirvagent migrate --force      Migrate without confirmation")
}

func agentCmd() {
	message := ""
	sessionKey := "cli:default"

	args := os.Args[2:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--debug", "-d":
			logger.SetLevel(logger.DEBUG)
			fmt.Println("🔍 Debug mode enabled")
		case "-m", "--message":
			if i+1 < len(args) {
				message = args[i+1]
				i++
			}
		case "-s", "--session":
			if i+1 < len(args) {
				sessionKey = args[i+1]
				i++
			}
		}
	}

	cfg, err := loadConfig()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		os.Exit(1)
	}

	provider, err := providers.CreateProvider(cfg)
	if err != nil {
		fmt.Printf("Error creating provider: %v\n", err)
		os.Exit(1)
	}

	msgBus := bus.NewMessageBus()
	agentLoop := agent.NewAgentLoop(cfg, msgBus, provider)

	// Print agent startup info (only for interactive mode)
	startupInfo := agentLoop.GetStartupInfo()
	logger.InfoCF("agent", "Agent initialized",
		map[string]interface{}{
			"tools_count":      startupInfo["tools"].(map[string]interface{})["count"],
			"skills_total":     startupInfo["skills"].(map[string]interface{})["total"],
			"skills_available": startupInfo["skills"].(map[string]interface{})["available"],
		})

	if message != "" {
		ctx := context.Background()
		response, err := agentLoop.ProcessDirect(ctx, message, sessionKey)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			os.Exit(1)
		}
		fmt.Printf("\n%s %s\n", logo, response)
	} else {
		fmt.Printf("%s Interactive mode (Ctrl+C to exit)\n\n", logo)
		interactiveMode(agentLoop, sessionKey)
	}
}

func interactiveMode(agentLoop *agent.AgentLoop, sessionKey string) {
	prompt := fmt.Sprintf("%s You: ", logo)

	rl, err := readline.NewEx(&readline.Config{
		Prompt:          prompt,
		HistoryFile:     filepath.Join(os.TempDir(), ".knirvagent_history"),
		HistoryLimit:    100,
		InterruptPrompt: "^C",
		EOFPrompt:       "exit",
	})

	if err != nil {
		fmt.Printf("Error initializing readline: %v\n", err)
		fmt.Println("Falling back to simple input mode...")
		simpleInteractiveMode(agentLoop, sessionKey)
		return
	}
	defer rl.Close()

	for {
		line, err := rl.Readline()
		if err != nil {
			if err == readline.ErrInterrupt || err == io.EOF {
				fmt.Println("\nGoodbye!")
				return
			}
			fmt.Printf("Error reading input: %v\n", err)
			continue
		}

		input := strings.TrimSpace(line)
		if input == "" {
			continue
		}

		if input == "exit" || input == "quit" {
			fmt.Println("Goodbye!")
			return
		}

		ctx := context.Background()
		response, err := agentLoop.ProcessDirect(ctx, input, sessionKey)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			continue
		}

		fmt.Printf("\n%s %s\n\n", logo, response)
	}
}

func simpleInteractiveMode(agentLoop *agent.AgentLoop, sessionKey string) {
	reader := bufio.NewReader(os.Stdin)
	for {
		fmt.Printf("%s You: ", logo)
		line, err := reader.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				fmt.Println("\nGoodbye!")
				return
			}
			fmt.Printf("Error reading input: %v\n", err)
			continue
		}

		input := strings.TrimSpace(line)
		if input == "" {
			continue
		}

		if input == "exit" || input == "quit" {
			fmt.Println("Goodbye!")
			return
		}

		ctx := context.Background()
		response, err := agentLoop.ProcessDirect(ctx, input, sessionKey)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			continue
		}

		fmt.Printf("\n%s %s\n\n", logo, response)
	}
}

func gatewayCmd() {
	// Check for --debug flag
	args := os.Args[2:]
	for _, arg := range args {
		if arg == "--debug" || arg == "-d" {
			logger.SetLevel(logger.DEBUG)
			fmt.Println("🔍 Debug mode enabled")
			break
		}
	}

	cfg, err := loadConfig()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		os.Exit(1)
	}

	provider, err := providers.CreateProvider(cfg)
	if err != nil {
		fmt.Printf("Error creating provider: %v\n", err)
		os.Exit(1)
	}

	msgBus := bus.NewMessageBus()
	agentLoop := agent.NewAgentLoop(cfg, msgBus, provider)

	// Print agent startup info
	fmt.Println("\n📦 Agent Status:")
	startupInfo := agentLoop.GetStartupInfo()
	toolsInfo := startupInfo["tools"].(map[string]interface{})
	skillsInfo := startupInfo["skills"].(map[string]interface{})
	fmt.Printf("  • Tools: %d loaded\n", toolsInfo["count"])
	fmt.Printf("  • Skills: %d/%d available\n",
		skillsInfo["available"],
		skillsInfo["total"])

	// Log to file as well
	logger.InfoCF("agent", "Agent initialized",
		map[string]interface{}{
			"tools_count":      toolsInfo["count"],
			"skills_total":     skillsInfo["total"],
			"skills_available": skillsInfo["available"],
		})

	// Setup cron tool and service
	cronService := setupCronTool(agentLoop, msgBus, cfg.WorkspacePath())

	heartbeatService := heartbeat.NewHeartbeatService(
		cfg.WorkspacePath(),
		cfg.Heartbeat.Interval,
		cfg.Heartbeat.Enabled,
	)
	heartbeatService.SetBus(msgBus)
	heartbeatService.SetHandler(func(prompt, channel, chatID string) *tools.ToolResult {
		// Use cli:direct as fallback if no valid channel
		if channel == "" || chatID == "" {
			channel, chatID = "cli", "direct"
		}
		// Use ProcessHeartbeat - no session history, each heartbeat is independent
		response, err := agentLoop.ProcessHeartbeat(context.Background(), prompt, channel, chatID)
		if err != nil {
			return tools.ErrorResult(fmt.Sprintf("Heartbeat error: %v", err))
		}
		if response == "HEARTBEAT_OK" {
			return tools.SilentResult("Heartbeat OK")
		}
		// For heartbeat, always return silent - the subagent result will be
		// sent to user via processSystemMessage when the async task completes
		return tools.SilentResult(response)
	})

	channelManager, err := channels.NewManager(cfg, msgBus)
	if err != nil {
		fmt.Printf("Error creating channel manager: %v\n", err)
		os.Exit(1)
	}

	var transcriber *voice.GroqTranscriber
	if cfg.Providers.Groq.APIKey != "" {
		transcriber = voice.NewGroqTranscriber(cfg.Providers.Groq.APIKey)
		logger.InfoC("voice", "Groq voice transcription enabled")
	}

	if transcriber != nil {
		if telegramChannel, ok := channelManager.GetChannel("telegram"); ok {
			if tc, ok := telegramChannel.(*channels.TelegramChannel); ok {
				tc.SetTranscriber(transcriber)
				logger.InfoC("voice", "Groq transcription attached to Telegram channel")
			}
		}
		if discordChannel, ok := channelManager.GetChannel("discord"); ok {
			if dc, ok := discordChannel.(*channels.DiscordChannel); ok {
				dc.SetTranscriber(transcriber)
				logger.InfoC("voice", "Groq transcription attached to Discord channel")
			}
		}
		if slackChannel, ok := channelManager.GetChannel("slack"); ok {
			if sc, ok := slackChannel.(*channels.SlackChannel); ok {
				sc.SetTranscriber(transcriber)
				logger.InfoC("voice", "Groq transcription attached to Slack channel")
			}
		}
	}

	enabledChannels := channelManager.GetEnabledChannels()
	if len(enabledChannels) > 0 {
		fmt.Printf("✓ Channels enabled: %s\n", enabledChannels)
	} else {
		fmt.Println("⚠ Warning: No channels enabled")
	}

	fmt.Printf("✓ Gateway started on %s:%d\n", cfg.Gateway.Host, cfg.Gateway.Port)
	fmt.Println("Press Ctrl+C to stop")

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	if err := cronService.Start(); err != nil {
		fmt.Printf("Error starting cron service: %v\n", err)
	}
	fmt.Println("✓ Cron service started")

	if err := heartbeatService.Start(); err != nil {
		fmt.Printf("Error starting heartbeat service: %v\n", err)
	}
	fmt.Println("✓ Heartbeat service started")

	stateManager := state.NewManager(cfg.WorkspacePath())
	deviceService := devices.NewService(devices.Config{
		Enabled:    cfg.Devices.Enabled,
		MonitorUSB: cfg.Devices.MonitorUSB,
	}, stateManager)
	deviceService.SetBus(msgBus)
	if err := deviceService.Start(ctx); err != nil {
		fmt.Printf("Error starting device service: %v\n", err)
	} else if cfg.Devices.Enabled {
		fmt.Println("✓ Device event service started")
	}

	if err := channelManager.StartAll(ctx); err != nil {
		fmt.Printf("Error starting channels: %v\n", err)
	}

	go agentLoop.Run(ctx)

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt)
	<-sigChan

	fmt.Println("\nShutting down...")
	cancel()
	deviceService.Stop()
	heartbeatService.Stop()
	cronService.Stop()
	agentLoop.Stop()
	channelManager.StopAll(ctx)
	fmt.Println("✓ Gateway stopped")
}

// serverCmd starts an HTTP server on a Unix socket that accepts command
// execution requests. Designed for use as a managed subprocess by KNIRVSERVER's
// AgentManager — each DVE gets its own agent process with its own socket.
//
// Usage: knirvagent server --dve-id <id> --socket-path <path>
func serverCmd() {
	dveID := ""
	socketPath := ""

	args := os.Args[2:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--dve-id":
			if i+1 < len(args) {
				dveID = args[i+1]
				i++
			}
		case "--socket-path":
			if i+1 < len(args) {
				socketPath = args[i+1]
				i++
			}
		case "--debug", "-d":
			logger.SetLevel(logger.DEBUG)
		case "--help", "-h":
			fmt.Println("Usage: knirvagent server --dve-id <id> --socket-path <path>")
			fmt.Println()
			fmt.Println("Starts the agent as an HTTP server on a Unix socket.")
			fmt.Println("Accepts POST /api/execute for command execution,")
			fmt.Println("GET /health for health checks.")
			return
		}
	}

	if socketPath == "" {
		fmt.Fprintf(os.Stderr, "Error: --socket-path is required\n")
		os.Exit(1)
	}

	// Remove any existing socket file
	os.Remove(socketPath)

	cfg, err := loadConfig()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading config: %v\n", err)
		os.Exit(1)
	}

	// Debug: log what the config actually has after loading
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Providers.Gemini.APIKey=%q (len=%d)\n",
		cfg.Providers.Gemini.APIKey, len(cfg.Providers.Gemini.APIKey))
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Providers.DeepSeek.APIKey=%q (len=%d)\n",
		cfg.Providers.DeepSeek.APIKey, len(cfg.Providers.DeepSeek.APIKey))
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Providers.ShengSuanYun.APIKey=%q (len=%d)\n",
		cfg.Providers.ShengSuanYun.APIKey, len(cfg.Providers.ShengSuanYun.APIKey))
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Providers.OpenRouter.APIKey=%q (len=%d)\n",
		cfg.Providers.OpenRouter.APIKey, len(cfg.Providers.OpenRouter.APIKey))
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Agents.Defaults.Provider=%q\n",
		cfg.Agents.Defaults.Provider)
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: cfg.Agents.Defaults.Model=%q\n",
		cfg.Agents.Defaults.Model)

	// Debug: log whether API keys are available as env vars
	for _, key := range []string{"GEMINI_API_KEY", "DEEPSEEK_API_KEY", "CEREBRAS_API_KEY", "ANTHROPIC_API_KEY", "OPENAI_API_KEY"} {
		if val, ok := os.LookupEnv(key); ok && val != "" {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: %s is set (len=%d)\n", key, len(val))
		} else if ok {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: %s is set but EMPTY\n", key)
		} else {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DEBUG: %s is NOT SET\n", key)
		}
	}

	provider, err := createProviderWithFallback(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error creating provider: %v\n", err)
		os.Exit(1)
	}

	// Build runtime fallback providers so the agent can switch on auth errors.
	// We pre-create each provider here (at startup) so there's no overhead at
	// the time of the actual fallback.
	runtimeFallbacks := buildRuntimeFallbacks(cfg)

	// Validate the primary provider with a quick test call and promote the
	// first working fallback when the primary key is invalid.  This runs before
	// the socket is created so the parent (AgentManager) always sees the
	// correct provider name in the health endpoint.
	provider, runtimeFallbacks = validateAndPromoteProvider(provider, cfg, runtimeFallbacks)

	// Create the Unix socket FIRST, before any potentially-blocking agent
	// initialization.  This ensures the parent (AgentManager.StartAgent)
	// sees the socket immediately via waitForSocket, avoiding the 30-second
	// timeout that would otherwise kill the agent process.
	listener, err := net.Listen("unix", socketPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error listening on socket %s: %v\n", socketPath, err)
		os.Exit(1)
	}
	defer listener.Close()
	defer os.Remove(socketPath)

	// Set permissions so the backend_server can connect
	os.Chmod(socketPath, 0666)

	msgBus := bus.NewMessageBus()
	agentLoop := agent.NewAgentLoop(cfg, msgBus, provider)
	agentLoop.SetFallbackProviders(runtimeFallbacks)

	// Start the agent loop in the background
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go agentLoop.Run(ctx)

	// Print startup info
	startupInfo := agentLoop.GetStartupInfo()
	toolsInfo := startupInfo["tools"].(map[string]interface{})
	skillsInfo := startupInfo["skills"].(map[string]interface{})
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] DVE=%s socket=%s tools=%d skills=%d/%d\n",
		dveID, socketPath, toolsInfo["count"], skillsInfo["available"], skillsInfo["total"])

	mux := http.NewServeMux()
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"status":   "ok",
			"dve_id":   dveID,
			"provider": cfg.Agents.Defaults.Provider,
			"model":    cfg.Agents.Defaults.Model,
		})
	})
	mux.HandleFunc("/api/execute", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "POST" {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var req struct {
			Command string `json:"command"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			json.NewEncoder(w).Encode(map[string]interface{}{
				"success": false,
				"error":   "invalid request: " + err.Error(),
			})
			return
		}

		if req.Command == "" {
			json.NewEncoder(w).Encode(map[string]interface{}{
				"success": false,
				"error":   "command is required",
			})
			return
		}

		// Use the HTTP request's context so that if the caller (KNIRVSERVER
		// WebSocket proxy) disconnects or times out, the LLM call is cancelled
		// rather than continuing to consume the server-wide context.
		response, err := agentLoop.ProcessDirect(r.Context(), req.Command, dveID+":terminal")
		if err != nil {
			json.NewEncoder(w).Encode(map[string]interface{}{
				"success": false,
				"error":   err.Error(),
			})
			return
		}

		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"output":  response,
		})
	})

	// Register inner agent hierarchy routes (spawn/install/sessions/tools/
	// input/stream/log for child AI agents such as Claude Code, Aider, Codex).
	// Inner agent PTY sessions must operate inside the same workspace root as the
	// supervisor agent for this DVE. KNIRVSERVER sets KNIRV_AGENTS_DEFAULTS_WORKSPACE
	// per DVE so both paths point at the DVE OverlayFS merged/ root.
	innerWorkspace := cfg.WorkspacePath()
	if err := os.MkdirAll(innerWorkspace, 0755); err != nil {
		fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Warning: could not create workspace %s: %v\n", innerWorkspace, err)
	}
	innerMgr := inner.NewInnerAgentManager(dveID, innerWorkspace)
	server.RegisterInnerRoutes(mux, innerMgr)

	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Listening on %s\n", socketPath)

	// Serve until shutdown signal
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)

	go func() {
		<-sigChan
		fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Shutting down...\n")
		cancel()
		listener.Close()
	}()

	if err := http.Serve(listener, mux); err != nil {
		if !strings.Contains(err.Error(), "use of closed network connection") {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Server error: %v\n", err)
		}
	}

	agentLoop.Stop()
	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Stopped\n")
}

// ──────────────────────────────────────────────
// Provider fallback — try configured provider first, then fall back through
// alternative providers that have API keys configured.  This lets the agent
// start even when the default model (gemini-2.0-flash / Gemini) has no key
// but other providers (DeepSeek, ShengSuanYun, OpenAI, etc.) do.
// ──────────────────────────────────────────────

// providerFallback defines one candidate in the fallback chain.
type providerFallback struct {
	Provider string
	Model    string // empty means leave the model at whatever CreateProvider picks
}

// defaultFallbackChain is the order of providers to try, from most preferred
// to least.  The first entry is always the user-configured provider/model.
var defaultFallbackChain = []providerFallback{
	// Entry 0 is a sentinel — filled in at runtime with the configured provider/model.
	{Provider: "", Model: ""},
	{Provider: "deepseek", Model: "deepseek-chat"},
	{Provider: "shengsuanyun", Model: ""},
	{Provider: "openai", Model: "gpt-4o-mini"},
	{Provider: "anthropic", Model: "claude-sonnet-4-20250514"},
	{Provider: "groq", Model: "llama-3.3-70b-versatile"},
	// Last resort — use OpenRouter if any key is set.  It proxies many models.
	{Provider: "openrouter", Model: "google/gemini-2.0-flash"},
}

// hasAPIKeyFor returns true when the given provider has a non-empty API key
// in the config.  This avoids attempting provider creation only to fail again.
func hasAPIKeyFor(cfg *config.Config, providerName string) bool {
	switch strings.ToLower(providerName) {
	case "gemini", "google":
		return cfg.Providers.Gemini.APIKey != ""
	case "deepseek":
		return cfg.Providers.DeepSeek.APIKey != ""
	case "shengsuanyun", "cerebras":
		return cfg.Providers.ShengSuanYun.APIKey != ""
	case "openai", "gpt":
		return cfg.Providers.OpenAI.APIKey != "" || cfg.Providers.OpenAI.AuthMethod != ""
	case "anthropic", "claude":
		return cfg.Providers.Anthropic.APIKey != "" || cfg.Providers.Anthropic.AuthMethod != ""
	case "openrouter":
		return cfg.Providers.OpenRouter.APIKey != ""
	case "groq":
		return cfg.Providers.Groq.APIKey != ""
	case "vllm":
		return cfg.Providers.VLLM.APIBase != ""
	default:
		return false
	}
}

// createProviderWithFallback tries the configured provider first.  If it
// fails (e.g. no API key for the default model), it walks the fallback chain
// looking for a provider with an available API key.  When a fallback succeeds,
// it updates cfg.Agents.Defaults so the rest of the agent (subagent manager,
// context builder, etc.) uses the correct provider and model.
func createProviderWithFallback(cfg *config.Config) (providers.LLMProvider, error) {
	// Build the chain starting with the user-configured provider/model.
	chain := make([]providerFallback, len(defaultFallbackChain))
	copy(chain, defaultFallbackChain)
	chain[0] = providerFallback{
		Provider: cfg.Agents.Defaults.Provider,
		Model:    cfg.Agents.Defaults.Model,
	}

	origProvider := cfg.Agents.Defaults.Provider
	origModel := cfg.Agents.Defaults.Model

	for i, fb := range chain {
		if fb.Provider == "" {
			continue
		}
		if !hasAPIKeyFor(cfg, fb.Provider) {
			continue
		}

		cfg.Agents.Defaults.Provider = fb.Provider
		if fb.Model != "" {
			cfg.Agents.Defaults.Model = fb.Model
		}

		provider, err := providers.CreateProvider(cfg)
		if err == nil {
			if i > 0 {
				fmt.Fprintf(os.Stderr,
					"[KNIRVAGENT] Provider %q (model: %q) unavailable, "+
						"falling back to %q (model: %q)\n",
					chain[0].Provider, chain[0].Model,
					fb.Provider, cfg.Agents.Defaults.Model)
			}
			return provider, nil
		}

		// Restore before trying the next fallback
		cfg.Agents.Defaults.Provider = origProvider
		cfg.Agents.Defaults.Model = origModel
	}

	// Every provider failed — build a helpful error message
	var available []string
	for _, fb := range chain {
		if fb.Provider != "" && hasAPIKeyFor(cfg, fb.Provider) {
			available = append(available, fb.Provider)
		}
	}
	if len(available) > 0 {
		return nil, fmt.Errorf(
			"no usable provider: %q has no valid API key (models %q), "+
				"and fallback providers failed. "+
				"Available providers with keys: %v",
			chain[0].Provider, chain[0].Model, available)
	}
	return nil, fmt.Errorf(
		"no API keys configured for any provider. "+
			"Ensure root.key contains at least one API key "+
			"(Gemini, DeepSeek, etc.)")
}

// isStartupAuthError returns true when an API call error indicates an
// invalid or missing key (HTTP 400/401/403) rather than a transient failure.
func isStartupAuthError(err error) bool {
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "400") ||
		strings.Contains(msg, "401") ||
		strings.Contains(msg, "403") ||
		strings.Contains(msg, "invalid api key") ||
		strings.Contains(msg, "api key not found") ||
		strings.Contains(msg, "api_key_invalid") ||
		strings.Contains(msg, "unauthorized") ||
		strings.Contains(msg, "permission denied")
}

// validateAndPromoteProvider makes a minimal test call to the primary provider.
// If it fails with an auth error, each fallback is tried in order and the first
// working one is promoted to primary — its entry is removed from the returned
// fallback slice and cfg.Agents.Defaults is updated accordingly.
// Non-auth failures (rate limits, network issues) are logged but do not trigger
// promotion, so the agent still starts and may recover at runtime.
func validateAndPromoteProvider(
	primary providers.LLMProvider,
	cfg *config.Config,
	fallbacks []agent.FallbackEntry,
) (providers.LLMProvider, []agent.FallbackEntry) {
	testMsg := []providers.Message{{Role: "user", Content: "reply with: ok"}}
	testOpts := map[string]interface{}{"max_tokens": 5}

	valCtx, valCancel := context.WithTimeout(context.Background(), 10*time.Second)
	_, primaryErr := primary.Chat(valCtx, testMsg, nil, cfg.Agents.Defaults.Model, testOpts)
	valCancel()

	if primaryErr == nil {
		fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Provider %q passed auth validation\n", cfg.Agents.Defaults.Provider)
		return primary, fallbacks
	}

	if !isStartupAuthError(primaryErr) {
		fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Warning: primary provider %q test failed (non-auth, may recover): %v\n",
			cfg.Agents.Defaults.Provider, primaryErr)
		return primary, fallbacks
	}

	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Primary provider %q auth error at startup: %v — testing fallbacks\n",
		cfg.Agents.Defaults.Provider, primaryErr)

	for i, fb := range fallbacks {
		fbCtx, fbCancel := context.WithTimeout(context.Background(), 10*time.Second)
		_, err := fb.Provider.Chat(fbCtx, testMsg, nil, fb.Model, testOpts)
		fbCancel()

		if err == nil {
			cfg.Agents.Defaults.Provider = fb.Name
			cfg.Agents.Defaults.Model = fb.Model
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Promoted %q (model: %q) as primary provider\n", fb.Name, fb.Model)
			// Remove the promoted entry from fallbacks
			remaining := make([]agent.FallbackEntry, 0, len(fallbacks)-1)
			remaining = append(remaining, fallbacks[:i]...)
			remaining = append(remaining, fallbacks[i+1:]...)
			return fb.Provider, remaining
		}
		if isStartupAuthError(err) {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Fallback %q auth error, skipping\n", fb.Name)
		} else {
			fmt.Fprintf(os.Stderr, "[KNIRVAGENT] Fallback %q test failed (non-auth): %v, skipping\n", fb.Name, err)
		}
	}

	fmt.Fprintf(os.Stderr, "[KNIRVAGENT] No fallback passed auth validation — continuing with %q (may fail at runtime)\n",
		cfg.Agents.Defaults.Provider)
	return primary, fallbacks
}

// buildRuntimeFallbacks pre-creates all fallback providers (excluding the
// one already chosen as primary) so the AgentLoop can switch at runtime when
// an auth error occurs.  Providers with no API key are silently skipped.
func buildRuntimeFallbacks(cfg *config.Config) []agent.FallbackEntry {
	primaryProvider := strings.ToLower(cfg.Agents.Defaults.Provider)
	origProvider := cfg.Agents.Defaults.Provider
	origModel := cfg.Agents.Defaults.Model

	var entries []agent.FallbackEntry
	for _, fb := range defaultFallbackChain[1:] {
		if fb.Provider == "" {
			continue
		}
		if strings.EqualFold(fb.Provider, primaryProvider) {
			continue // already the primary
		}
		if !hasAPIKeyFor(cfg, fb.Provider) {
			continue
		}

		cfg.Agents.Defaults.Provider = fb.Provider
		if fb.Model != "" {
			cfg.Agents.Defaults.Model = fb.Model
		} else {
			cfg.Agents.Defaults.Model = origModel
		}

		p, err := providers.CreateProvider(cfg)
		if err != nil {
			cfg.Agents.Defaults.Provider = origProvider
			cfg.Agents.Defaults.Model = origModel
			continue
		}

		model := cfg.Agents.Defaults.Model
		entries = append(entries, agent.FallbackEntry{
			Provider: p,
			Model:    model,
			Name:     fb.Provider,
		})

		cfg.Agents.Defaults.Provider = origProvider
		cfg.Agents.Defaults.Model = origModel
	}

	return entries
}

func statusCmd() {
	cfg, err := loadConfig()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		return
	}

	configPath := getConfigPath()

	fmt.Printf("%s knirvagent Status\n", logo)
	fmt.Printf("Version: %s\n", formatVersion())
	build, _ := formatBuildInfo()
	if build != "" {
		fmt.Printf("Build: %s\n", build)
	}
	fmt.Println()

	if _, err := os.Stat(configPath); err == nil {
		fmt.Println("Config:", configPath, "✓")
	} else {
		fmt.Println("Config:", configPath, "✗")
	}

	workspace := cfg.WorkspacePath()
	if _, err := os.Stat(workspace); err == nil {
		fmt.Println("Workspace:", workspace, "✓")
	} else {
		fmt.Println("Workspace:", workspace, "✗")
	}

	if _, err := os.Stat(configPath); err == nil {
		fmt.Printf("Model: %s\n", cfg.Agents.Defaults.Model)

		hasOpenRouter := cfg.Providers.OpenRouter.APIKey != ""
		hasAnthropic := cfg.Providers.Anthropic.APIKey != ""
		hasOpenAI := cfg.Providers.OpenAI.APIKey != ""
		hasGemini := cfg.Providers.Gemini.APIKey != ""
		hasGroq := cfg.Providers.Groq.APIKey != ""
		hasVLLM := cfg.Providers.VLLM.APIBase != ""

		status := func(enabled bool) string {
			if enabled {
				return "✓"
			}
			return "not set"
		}
		fmt.Println("OpenRouter API:", status(hasOpenRouter))
		fmt.Println("Anthropic API:", status(hasAnthropic))
		fmt.Println("OpenAI API:", status(hasOpenAI))
		fmt.Println("Gemini API:", status(hasGemini))
		fmt.Println("Groq API:", status(hasGroq))
		if hasVLLM {
			fmt.Printf("vLLM/Local: ✓ %s\n", cfg.Providers.VLLM.APIBase)
		} else {
			fmt.Println("vLLM/Local: not set")
		}

		store, _ := auth.LoadStore()
		if store != nil && len(store.Credentials) > 0 {
			fmt.Println("\nOAuth/Token Auth:")
			for provider, cred := range store.Credentials {
				status := "authenticated"
				if cred.IsExpired() {
					status = "expired"
				} else if cred.NeedsRefresh() {
					status = "needs refresh"
				}
				fmt.Printf("  %s (%s): %s\n", provider, cred.AuthMethod, status)
			}
		}
	}
}

func authCmd() {
	if len(os.Args) < 3 {
		authHelp()
		return
	}

	switch os.Args[2] {
	case "login":
		authLoginCmd()
	case "logout":
		authLogoutCmd()
	case "status":
		authStatusCmd()
